var root = element.shadowRoot;
if (!root) return;
var expanderLink = root.querySelector('#expander-item a#endpoint');
if (expanderLink && !element._isExpanded) {
  expanderLink.click();
}

if (typeof element.showMore === 'function') {
  element.showMore();
} else if (typeof element.toggleExpanded === 'function') {
  element.toggleExpanded();
}

// Try setting internal state directly
element.setAttribute('expanded', '');
if (element._isExpanded === false || element._isExpanded === undefined) {
  element._isExpanded = true;
}
// Also try notifying Polymer of the change
if (typeof element.fire === 'function') {
  element.fire('toggle-expanded');
}

var root = element.shadowRoot;
if (!root) return;
var expanderLink = root.querySelector('#expander-item a#endpoint');
if (!expanderLink) return;

// Try dispatching from the shadow root's document context
try {
  var clickEvent = new root.ownerDocument.defaultView.MouseEvent('click', { bubbles: true, cancelable: true });
  expanderLink.dispatchEvent(clickEvent);
} catch(e) {
  // fallback
  try {
    var evt = root.ownerDocument.createEvent('MouseEvents');
    evt.initMouseEvent('click', true, true, root.ownerDocument.defaultView, 1, 0, 0, 0, 0, false, false, false, false, 0, null);
    expanderLink.dispatchEvent(evt);
  } catch(e2) {
    expanderLink.click();
  }
}

// Check what methods are available on the element
var methods = [];
for (var key in element) {
  if (typeof element[key] === 'function') {
    methods.push(key);
  }
}
element.textContent = ''; // temp debug - won't actually work on custom elements

// Try to access internal properties that might hold the continuation token
if (element.items && element.items.length > 0) {
  // items already loaded
}
// Check for endpoint/continuation data
var root = element.shadowRoot;
if (root) {
  var expander = root.querySelector('#expander-item');
  if (expander && expander.endpoint) {
    // There might be an endpoint we can use
  }
}

var root = element.shadowRoot;
if (!root) return;

// Try clicking the yt-interaction element instead
var interaction = root.querySelector('#expander-item yt-interaction');
if (interaction) {
  var innerDiv = interaction.querySelector('div.stroke');
  if (innerDiv) {
    innerDiv.click();
  }
}

// Also try the tp-yt-paper-item
var paperItem = root.querySelector('#expander-item tp-yt-paper-item');
if (paperItem) {
  paperItem.click();
}

var root = element.shadowRoot;
if (!root) return;

// Hide the "Show more" expander button
var expanderItem = root.querySelector('#expander-item');
if (expanderItem) {
  expanderItem.style.display = 'none';
}

// Hide the "Show less" collapser button
var collapserItem = root.querySelector('#collapser-item');
if (collapserItem) {
  collapserItem.style.display = 'none';
}

// Make the expanded area visible and ensure items container is shown
var expanded = root.querySelector('#expanded');
if (expanded) {
  expanded.style.display = 'block';
}

var expandableItems = root.querySelector('#expandable-items');
if (expandableItems) {
  expandableItems.style.display = 'block';
}

// Set expanded attribute to keep it in expanded state
element.setAttribute('expanded', '');

// Try to find and use the continuation endpoint
var root = element.shadowRoot;
if (!root) return;

// Check if items are already loaded in expandable-items
var expandableItems = root.querySelector('#expandable-items');
if (expandableItems && expandableItems.children.length > 0) {
  return; // Already expanded
}

// Try to get the endpoint from the expander
var expanderLink = root.querySelector('#expander-item a#endpoint');
if (expanderLink && expanderLink.href) {
  // The href might contain the continuation or navigation endpoint
  // YouTube uses inner API for these
}

// Check element properties for continuation info
if (element.endpoint) {
  // There's an endpoint property
}

// Try various internal methods that Polymer/Lit elements might have
var methodsToTry = ['showMore', 'toggleExpanded', '_handleShowMore', '_toggleExpanded', 'expand', 'open'];
for (var i = 0; i < methodsToTry.length; i++) {
  var method = methodsToTry[i];
  if (typeof element[method] === 'function') {
    try {
      element[method]();
    } catch(e) {}
  }
}

// Also try setting properties that might trigger the expansion
if (!element.expanded) {
  element.expanded = true;
}
if (typeof element.set === 'function') {
  try { element.set('expanded', true); } catch(e) {}
}
